def apply_fixes(stem, choices):
    for sp, old, new in FIXES:
        if stem.startswith(sp):
            hit = [i for i, c in enumerate(choices) if c.startswith(old) or c == new]
            assert len(hit) == 1, (sp, old, hit)
            choices[hit[0]] = new
    return choices


def build():
    first = json.loads(OUT.read_text()) if OUT.exists() else []
    first = [q for q in first if q.get("origin") == ORIGIN][:10]   # 10 ข้อตัวอย่างที่อนุมัติแนวแล้ว (เขียนมือ ไม่สลับ)
    rng = random.Random(20261104)
    for q in first:
        q["choices"] = apply_fixes(q["stem"], q["choices"])
    out = list(first)
    for group in (B2, A3, B1):
        slots = [i % 4 for i in range(len(group))]
        rng.shuffle(slots)
        for (topic, level, law_ref, stem, correct, wrong, why), pos in zip(group, slots):
            assert len(wrong) == 3, stem
            choices = list(wrong)
            rng.shuffle(choices)
            choices.insert(pos, correct)
            choices = apply_fixes(stem, choices)
            out.append(dict(topic=topic, level=level, law_ref=law_ref, stem=stem, choices=choices, answer=pos,
                            explanation=why, source="claude:authored", status="review", origin=ORIGIN))
    stems = [q["stem"] for q in out]
    assert len(stems) == len(set(stems)), "duplicate stem"
    OUT.write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n")
    by = Counter(q["topic"][:2] for q in out)
    print(len(out), dict(by))
    for g in ("B2", "A3", "B1"):
        print(g, sorted(Counter(q["answer"] for q in out if q["topic"].startswith(g)).items()))
    longest = sum(1 for q in out if max(range(4), key=lambda i: len(q["choices"][i])) == q["answer"])
    print("correct is the longest choice:", longest, "of", len(out))


if __name__ == "__main__":
    build()
